-- Dansk portion 1 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6580-9975.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish1'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish1', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6580,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der altid stå komma: 'Fordi Ali var syg da vi tog af sted kom han ikke med.'?","o":["Ali","kom","sted","han"],"a":"sted","r":"Begge ledsætninger er slut efter 'sted', og så begynder hovedsætningen med 'kom han ikke med'."},
{"l":6600,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Slottet tilhører kongen af Danmark. Hvilken form er rigtig?","o":["kongens af Danmark slot","kongen's af Danmark slot","kongen af Danmark's slot","kongen af Danmarks slot"],"a":"kongen af Danmarks slot","r":"Når ejeren består af flere ord, sættes genitiv-s på det sidste ord i gruppen, uden apostrof."},
{"l":6620,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor bruges der apostrof i 'pc'en'?","o":["Fordi endelsen sættes på en forkortelse","Fordi der er udeladt et bogstav her","Fordi ordet står i genitiv her","Fordi ordet er et egennavn her"],"a":"Fordi endelsen sættes på en forkortelse","r":"Pc er en forkortelse, og apostroffen viser grænsen mellem forkortelsen og endelsen."},
{"l":6642,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sætningsled er at-sætningen i: 'At Jonas vandt, overraskede alle.'?","o":["genstandsled","grundled","hensynsled","omsagnsled"],"a":"grundled","r":"Spørg: Hvad overraskede alle? Svaret er hele at-sætningen, så her fungerer ledsætningen som grundled."},
{"l":6664,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om døren viser passiv med 'blive' og en, der handler?","o":["Døren står åben hele dagen.","Døren ser meget gammel ud.","Døren bliver lukket af pedellen.","Døren ligger ud til gården."],"a":"Døren bliver lukket af pedellen.","r":"'Bliver lukket' er passiv med 'blive', og 'af pedellen' nævner den, der handler. De andre sætninger er aktive."},
{"l":6685,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en rammefortælling?","o":["En fortælling, der kun foregår i et enkelt lukket rum","En fortælling, der er sat ind i en ramme på et museum","En fortælling, som altid har præcis tre hovedpersoner","En fortælling, der rummer en anden fortælling inde i sig"],"a":"En fortælling, der rummer en anden fortælling inde i sig","r":"Rammen er den ydre historie, f.eks. en gruppe, der mødes. Inde i rammen fortælles så en anden historie."},
{"l":6701,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Den, der har haft skoldkopper, er som regel 'immun' mod sygdommen. Hvad betyder det?","o":["man får normalt ikke sygdommen igen","man får sygdommen igen hvert år","man smitter alle omkring sig","man skal have medicin resten af livet"],"a":"man får normalt ikke sygdommen igen","r":"Kroppens forsvar husker sygdommen og kan bekæmpe den hurtigt. Vacciner bygger på det samme princip."},
{"l":6721,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Hun tog imod ___ uden at blive sur.'","o":["krittik","kritik","kretik","kritick"],"a":"kritik","r":"Ordet har kun ét t og slutter på -ik, som mange ord fra græsk."},
{"l":6746,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Når jern ruster, sker der en 'oxidation'. Hvilket stof reagerer jernet med?","o":["brint","kvælstof","ilt","kulstof"],"a":"ilt","r":"Oxidation kommer af 'oxygen', det internationale navn for ilt. Jern ruster, når det reagerer med ilt ved hjælp af fugt."},
{"l":6763,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå: '___ barn i klassen får en bog.'?","o":["Hver","Alle","Mange","Hvert"],"a":"Hvert","r":"'Barn' er et intetkønsord i ental, så stedordet skal hedde 'hvert'. Det kaldes kongruens. 'Alle' og 'mange' kræver flertal."},
{"l":6785,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå: 'Der kom ___ tilskuere i år, kun halvt så mange som sidst.'?","o":["færre","mindre","mere","færrest"],"a":"færre","r":"Om ting og personer, man kan tælle, bruger man 'færre'. 'Mindre' bruger man om størrelse og om det, der ikke kan tælles."},
{"l":6800,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forskeren sagde til avisen: Det kunne tænkes, at kost spiller en rolle. Avisens overskrift lød: Forsker: Det er bevist, at kost afgør det hele.' Hvad er der sket?","o":["Forskerens forbehold er blevet tydeligere i avisen","En forsigtig mulighed er blevet til en stor sikkerhed","Avisen har citeret forskeren ordret og uden ændringer","Forskeren har skiftet mening efter at have talt med avisen"],"a":"En forsigtig mulighed er blevet til en stor sikkerhed","r":"'Kunne tænkes' er noget helt andet end 'bevist', og 'en rolle' er noget andet end 'det hele'. Det er en typisk fejl i formidling."},
{"l":6818,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvem har mest sandsynligt skrevet: 'Ansøgningen skal indsendes senest den 1. marts.'?","o":["en ven på sms","et barn i sin dagbog","en offentlig myndighed","en sportsreporter"],"a":"en offentlig myndighed","r":"Passiv uden nævnt afsender og ord som 'indsendes' og 'senest' er typisk for formelt myndighedssprog."},
{"l":6838,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Frederik talte altid højt om sine dyre sko og sit store hus, men han spurgte aldrig til andre.' Hvilket træk passer bedst på Frederik?","o":["genert","hjælpsom","nysgerrig","selvoptaget"],"a":"selvoptaget","r":"Han taler kun om sig selv og interesserer sig ikke for andre. Vi slutter det af hans handlinger, så det er indirekte karakteristik."},
{"l":6860,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er grundleddet i: 'Den varme kakao drak Freja hurtigt.'?","o":["Freja","Den varme kakao","drak","hurtigt"],"a":"Freja","r":"Spørg: Hvem drak? Det er Freja. Genstandsleddet 'den varme kakao' står først for at blive fremhævet, men det er stadig ikke grundled."},
{"l":6880,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Prinsen vil redde prinsessen, men heksen forsøger at stoppe ham.' Hvilken rolle har heksen i aktantmodellen?","o":["hjælper","modstander","subjekt","objekt"],"a":"modstander","r":"Heksen står i vejen for det, prinsen vil opnå. Prinsen er subjekt, og prinsessen er objekt."},
{"l":6900,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning om vejret bruger semikolon rigtigt?","o":["Regnen holdt; op solen kom frem over marken.","Da regnen holdt op; kom solen frem over marken.","Regnen holdt op; solen kom frem over marken.","Regnen holdt op og; solen kom frem over marken."],"a":"Regnen holdt op; solen kom frem over marken.","r":"Semikolon står mellem to hele hovedsætninger, der hører sammen. Det må ikke stå efter en ledsætning."},
{"l":6916,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'En ___ på tv skal få os til at købe noget.'","o":["rekklame","reklamme","riklame","reklame"],"a":"reklame","r":"Ordet har ét k og ét m."},
{"l":6940,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Den lange flod nilen løber gennem Egypten.'?","o":["nilen","flod","lange","løber"],"a":"nilen","r":"Nilen er navnet på en bestemt flod. 'Flod' er et almindeligt navneord og skrives med lille."},
{"l":6959,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Alle elever i 7. klasse er inviteret til frivillig lektiecafé hver tirsdag. Fravær registreres og sendes hjem til forældrene.' Hvad er selvmodsigende ved beskeden?","o":["At lektiecaféen foregår om tirsdagen","At noget frivilligt behandles som en pligt","At alle elever er blevet inviteret","At forældrene bliver orienteret om tilbuddet"],"a":"At noget frivilligt behandles som en pligt","r":"Registreret fravær hører til et krav, ikke et tilbud. Den anden sætning undergraver ordet 'frivillig' fra den første."},
{"l":6981,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord siger relativsætningen noget om: 'Jeg så den kat i haven, som var løbet væk.'?","o":["haven","Jeg","kat","væk"],"a":"kat","r":"Det er katten, der var løbet væk, ikke haven. En relativsætning kan godt stå et stykke fra det ord, den hører til."},
{"l":7000,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg er ikke imod unge. Jeg siger bare, at de larmer, ødelægger bænkene og bør være indendørs efter klokken 20.' Hvad er problemet med den første sætning?","o":["Den oplyser ikke, hvor gammel skribenten er","Den siger ikke, hvilke bænke det drejer sig om","Den er skrevet i jeg-form i stedet for vi-form","Den modsiges af alt det, der følger bagefter"],"a":"Den modsiges af alt det, der følger bagefter","r":"Sætningen fungerer som et skjold, så skribenten kan fremføre kritik af unge uden at kaldes imod dem."},
{"l":7018,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forskerne tager en 'stikprøve' blandt landets elever. Hvad gør de?","o":["undersøger nogle få for at sige noget om alle","undersøger hver eneste elev i hele landet","vælger kun de dygtigste elever ud","lader eleverne selv bestemme resultatet"],"a":"undersøger nogle få for at sige noget om alle","r":"En stikprøve er en lille del, der skal repræsentere helheden. Det er meget lettere end at spørge alle."},
{"l":7040,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem giver udtryk for sin holdning i en lederartikel?","o":["En tilfældig læser","Avisens redaktion","En ekspert udefra","Den interviewede person"],"a":"Avisens redaktion","r":"Lederen er avisens egen stemme. Den giver udtryk for avisens holdning til en aktuel sag."},
{"l":7059,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket sammensat ord er rigtigt? Det er stedet, hvor du har dit job.","o":["arbejdeplads","arbejdspladds","arbejdsplads","arbejdsplas"],"a":"arbejdsplads","r":"Ordet samles med et fuge-s. 'Plads' skrives med stumt d."},
{"l":7080,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvor mange kommaer skal der mindst stå i 'Da vi kom hjem var klokken mange og alle var trætte.'?","o":["ét komma","tre kommaer","intet komma","to kommaer"],"a":"to kommaer","r":"Der skal komma efter ledsætningen 'Da vi kom hjem' og foran 'og', fordi anden hovedsætning har sit eget grundled."},
{"l":7102,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Vi ses ___ gange om måneden.'?","o":["nogle","nogen","noget","enhver"],"a":"nogle","r":"'Gange' er flertal i en bekræftende sætning, og så skriver man 'nogle'. I talesprog lyder 'nogle' og 'nogen' ens, så man må tænke sig om, når man skriver."},
{"l":7124,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken modus står 'løber' i: 'Hun løber en tur hver morgen.'?","o":["imperativ","indikativ","konjunktiv","infinitiv"],"a":"indikativ","r":"Indikativ er den fortællende modus, som fremstiller noget som virkeligt. Imperativ er bydeform, og konjunktiv er ønskeform."},
{"l":7146,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolens nye app skulle gøre det let at melde sig til klubben. Det gør den. Nu skal jeg bare oprette en bruger, bekræfte min mail, vælge en kode med tre specialtegn og få en voksen til at godkende, at jeg kommer torsdag.' Hvad er skribentens kritik?","o":["Det er blevet for svært at finde på en god adgangskode","Klubben burde slet ikke kræve tilmelding om torsdagen","En løsning, der skulle spare besvær, har skabt nyt besvær","Voksne skal ikke blande sig i, hvornår børn går i klub"],"a":"En løsning, der skulle spare besvær, har skabt nyt besvær","r":"'Det gør den' er ironisk, for listen viser, at det er blevet sværere. Koden og den voksne er kun eksempler på besværet, ikke selve kritikken."},
{"l":7169,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hun havde dækket bord til ti. Klokken otte var der stadig ni tomme stole, og lysene var brændt halvt ned. Hun pustede dem ikke ud.' Hvad viser den sidste sætning?","o":["At hun er blevet glad for at være alene","At hun er ligeglad med stearinen på dugen","At hun har glemt, at lysene er tændt","At hun ikke har opgivet håbet om gæsterne"],"a":"At hun ikke har opgivet håbet om gæsterne","r":"At lade lysene brænde er det samme som at blive ved med at vente. Den lille handling viser, hvad hun ikke siger."},
{"l":7190,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket latinsk navn svarer til 'hensynsled'?","o":["indirekte objekt","direkte objekt","subjekt","verballed"],"a":"indirekte objekt","r":"Hensynsleddet er det indirekte objekt: den, der får noget, eller som handlingen sker for."},
{"l":7211,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet? 'Vi bor i et stille ___ uden for byen.'","o":["qvarter","kvarter","kvatter","kvartær"],"a":"kvarter","r":"Ordet skrives med kv, og r'et midt i ordet skal med."},
{"l":7227,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I hvilken sætning er ordet 'effektfuld' brugt rigtigt?","o":["Støvsugeren er effektfuld, for den bruger kun lidt strøm.","Bussen var effektfuld og kom til tiden hver eneste dag.","Slutscenen var så effektfuld, at hele salen gispede.","Hun er effektfuld og når altid sine lektier før aftensmaden."],"a":"Slutscenen var så effektfuld, at hele salen gispede.","r":"Noget effektfuldt gør et stærkt indtryk på dem, der ser eller hører det. Om en maskine eller en arbejdsmåde, der sparer tid og kræfter, skal man sige 'effektiv'."},
{"l":7249,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det var først, da toget kørte, at hun mærkede billetten i sin lomme. Den lå sammen med en seddel: Du har brug for den mere. På perronen stod han med hænderne tomme og vinkede.' Hvad er der sket?","o":["Hun har stjålet billetten fra ham uden at vide det","Han har købt billetter til dem begge i sidste øjeblik","Hun har glemt ham på perronen, da toget kørte","Han har givet hende sin egen billet og bliver tilbage"],"a":"Han har givet hende sin egen billet og bliver tilbage","r":"Sedlen viser, at billetten er blevet givet med vilje, og at han står tilbage. De tomme hænder understreger det."},
{"l":7271,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En mand købte et ur, der gik perfekt. Han hængte det så højt på væggen, at ingen kunne røre det. Efter et år var det gået i stå, for heller ikke han selv kunne nå at trække det op.' Hvad er historiens morale?","o":["Det, man beskytter for meget, får man ikke glæde af","Man skal aldrig købe et ur, man ikke har råd til","Man skal altid have en høj stige stående i huset","Det nytter ikke at hænge noget op på væggen"],"a":"Det, man beskytter for meget, får man ikke glæde af","r":"Uret overlever ikke overdreven beskyttelse. Historien bruger det konkrete ur til at fortælle en almen pointe."},
{"l":7295,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord kan erstatte 'essentiel' i udtrykket 'en essentiel del af opgaven'?","o":["valgfri","afgørende","afsluttende","indledende"],"a":"afgørende","r":"Essentiel kommer af 'essens', som betyder kerne. En essentiel del er altså en del, man ikke kan undvære."},
{"l":7310,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad menes der med 'ressourcer', når avisen skriver, at en skole mangler ressourcer?","o":["regler, love og bestemmelser","elever, klasser og årgange","penge, tid og andre midler","prøver, opgaver og karakterer"],"a":"penge, tid og andre midler","r":"Ressourcer er det, man har til rådighed for at få noget gjort. Det kan være penge, tid, personale eller materialer."},
{"l":7328,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hele natten bankede regnen på ruden, som om den ville ind og fortælle noget, hun ikke ville vide.' Hvilken virkning har måden, regnen beskrives på?","o":["Regnen beskrives køligt som et vejrfænomen","Regnen virker hyggelig og beroligende","Regnen fremstår som et sjovt indslag","Regnen gøres menneskelig, og det skaber uro"],"a":"Regnen gøres menneskelig, og det skaber uro","r":"Regnen får menneskelige hensigter, og det kaldes personificering. Den viser også noget om pigens indre uro."},
{"l":7351,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Elevernes trivsel er det vigtigste, siger alle på skolen. Men da der skulle spares, var det trivselslæreren, der måtte gå, og ikke det nye logo til 80.000 kroner.' Hvad er skribentens pointe?","o":["Skolens handling viser andre prioriteter end dens ord","Skolens nye logo er bedre end det, den havde før","Trivselslæreren har været dårlig til at gøre sit job","Skolen har sparet for meget på logoer og skilte"],"a":"Skolens handling viser andre prioriteter end dens ord","r":"Skribenten stiller ord og handling over for hinanden. Prisen på logoet skal vise, at der var andre muligheder."},
{"l":7370,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilke ord skal have stort: 'Vi så udstillingen på statens museum for kunst.'?","o":["alle fire ord, også for","statens, museum og kunst","kun statens","kun museum og kunst"],"a":"statens, museum og kunst","r":"Navnet er Statens Museum for Kunst. Små ord som 'for' inde i et navn skrives med lille."},
{"l":7392,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket tegn passer: 'Der var kun én ting at gøre ___ ringe efter hjælp.'?","o":["semikolon","apostrof","kolon","bindestreg"],"a":"kolon","r":"Første del lægger op til en forklaring, og kolon varsler den. Semikolon kræver en hel sætning bagefter."},
{"l":7407,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad mener man, når man siger, at nogen må 'sejle deres egen sø'?","o":["at de får hjælp hele vejen","at de bliver inviteret ud at sejle","at de bør lytte til andres råd","at de selv må klare følgerne"],"a":"at de selv må klare følgerne","r":"Den, der må sejle sin egen sø, får ikke længere hjælp fra andre. Udtrykket bruges ofte, når man har opgivet at råde en, der ikke vil høre."},
{"l":7426,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er en vandrehistorie?","o":["En moderne historie, der spredes som sand, men sjældent kan bevises","En rejseberetning, hvor en forfatter skildrer en lang vandretur","En gammel fortælling om guder, der skabte hele verden og mennesket","En novelle, hvor hovedpersonen vandrer hjemmefra og aldrig vender hjem"],"a":"En moderne historie, der spredes som sand, men sjældent kan bevises","r":"Vandrehistorier fortælles tit som noget, 'en vens ven' har oplevet. De er en slags moderne sagn."},
{"l":7446,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad handler en dannelsesroman om?","o":["En detektiv, der opklarer en svær forbrydelse","Et ungt menneske, der modnes og finder sin plads","En ældre lærer, der underviser på en højskole","En gruppe forskere, der rejser ud i rummet"],"a":"Et ungt menneske, der modnes og finder sin plads","r":"Dannelsesromanen følger hovedpersonens udvikling fra ung til voksen, med de erfaringer det kræver."},
{"l":7465,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Ingen i familien brugte ordet syg. Mor havde bare nogle dårlige dage, og der blev flere af dem. Vi lærte at gå stille på trappen.' Hvad viser sprogbrugen om familien?","o":["De ved ikke, at moren har dårlige dage","De synes, at det er hyggeligt at være stille","De undgår at tale åbent om det alvorlige","De lægger ikke mærke til morens tilstand"],"a":"De undgår at tale åbent om det alvorlige","r":"'Dårlige dage' er en mild omskrivning. Familien tilpasser sig uden at sige, hvad det egentlig handler om."},
{"l":7488,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi er en skole, hvor alle må sige deres mening, siger skolelederen. Tre elever, der har kritiseret det nye skema, er i denne uge blevet kaldt til samtale på kontoret, én ad gangen.' Hvad antyder journalisten ved at sætte de to sætninger sammen?","o":["At de tre elever er enige med skolelederen om skemaet","At skolelederen har for travlt til at tale med flere ad gangen","At skemaet er blevet ændret på grund af elevernes kritik","At friheden til at sige sin mening måske ikke er så stor"],"a":"At friheden til at sige sin mening måske ikke er så stor","r":"Journalisten kommenterer ikke selv, men rækkefølgen rejser tvivl. Det kan læseren aflæse af, at kritikere bliver kaldt ind enkeltvis."},
{"l":7502,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Den ___ grænse går lige syd for Tønder.'?","o":["dansk-tyske","dansk tyske","dansk:tyske","dansk'tyske"],"a":"dansk-tyske","r":"Når to sideordnede tillægsord beskriver det samme, bindes de sammen med bindestreg."},
{"l":7522,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hver sommer kører vi samme vej til sommerhuset. Far siger, at den er kortest. Mor siger, at den er pænest. Kortet siger ingenting, for det har ligget i handskerummet i otte år.' Hvad kan man slutte?","o":["Sommerhuset ligger længere væk end for otte år siden","Ingen af forældrene har undersøgt, om de har ret","Far og mor er rygende uenige om, hvor de skal køre","Familien har købt et nyt kort, der ikke bliver brugt"],"a":"Ingen af forældrene har undersøgt, om de har ret","r":"Kortet har ikke været fremme i otte år, så påstandene er ikke tjekket. De kører samme vej, så der er ikke tale om reel strid."},
{"l":7544,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken dramagenre ender typisk ulykkeligt for hovedpersonen?","o":["komedie","farce","tragedie","vaudeville"],"a":"tragedie","r":"Tragedien ender ulykkeligt, ofte fordi personen er fanget af sin skæbne eller sine fejl. Komedien ender godt."},
{"l":7564,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad angiver ledsætningen i: 'Det blæste så meget, at træet væltede.'?","o":["årsag","formål","indrømmelse","følge"],"a":"følge","r":"Ledsætningen fortæller, hvad blæsten førte til. Sammen med 'så meget' angiver 'at' her en følge."},
{"l":7588,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder nogenlunde det samme som 'indvending'?","o":["modargument","forudsætning","tilføjelse","påmindelse"],"a":"modargument","r":"En indvending er noget, man fremfører imod en påstand eller et forslag. Derfor er modargument det nærmeste ord."},
{"l":7608,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning betyder det samme som: 'Der tales dansk i klassen.'?","o":["Man talte dansk i klassen.","Man taler dansk i klassen.","Man skal tale dansk i klassen.","Dansk taler i klassen."],"a":"Man taler dansk i klassen.","r":"'Tales' er passiv i nutid. Når man gør sætningen aktiv uden at nævne nogen bestemt, bruger man ofte 'man' og beholder nutid."},
{"l":7628,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Fabrikkens sirene hylede klokken fem. Børnene slæbte sig af sted i iskold tåge, og lønnen rakte knap nok til brødet.' Hvilken periode minder teksten mest om?","o":["romantikken","oplysningstiden","det moderne gennembrud","barokken"],"a":"det moderne gennembrud","r":"En nøgtern skildring af fattigdom og arbejdsvilkår er typisk for det moderne gennembrud, hvor samfundets problemer skulle frem."},
{"l":7648,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad kendetegner en 'autodidakt'?","o":["en person, der har fået sit kørekort på første forsøg","en person, der kører en bil uden at bruge rattet","en person, der skriver sine egne bøger om sit liv","en person, der har lært sig noget uden undervisning"],"a":"en person, der har lært sig noget uden undervisning","r":"'Auto' betyder selv, og 'didakt' kommer af det græske ord for at undervise. En autodidakt har altså undervist sig selv."},
{"l":7670,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det var det år, vi holdt op med at sige godnat gennem væggen. Ingen besluttede det. Det skete bare, ligesom når man holder op med at bruge et ord.' Hvad handler teksten om?","o":["At barndommens nærhed stille forsvinder","At søskende bliver uvenner over en væg","At fortælleren er flyttet til et andet hus","At ordforrådet bliver mindre med alderen"],"a":"At barndommens nærhed stille forsvinder","r":"Vanen er ikke brudt med et skænderi, den ebber bare ud. Sammenligningen med ordet viser, hvor umærkeligt det sker."},
{"l":7693,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilken person kaldes en 'gemalinde' i ældre tekster?","o":["en konges datter","en fyrstes hustru","en ridders mor","en borgers søster"],"a":"en fyrstes hustru","r":"'Gemalinde' er et fint ord for en konges eller fyrstes kone. En regerende dronnings mand kaldes tilsvarende en 'gemal'."},
{"l":7707,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er en lang tillægsform brugt som navneord: 'En rejsende spurgte om vej til stationen.'?","o":["spurgte","vej","rejsende","stationen"],"a":"rejsende","r":"Lang tillægsform kan bruges som navneord. Her står 'en' foran 'rejsende', og ordet betegner en person."},
{"l":7729,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvorfor skal der i skriftsprog stå 'nogle' i: 'Nogle elever cyklede til hallen.'?","o":["Det står foran ental i et spørgsmål.","Det står altid først i en hel sætning.","Det er et ejestedord i flertalsform.","Det står foran flertal uden nægtelse."],"a":"Det står foran flertal uden nægtelse.","r":"'Elever' er flertal, og sætningen er bekræftende, altså uden nægtelse. Så er 'nogle' den rigtige form på skrift."},
{"l":7750,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bogen vil meget. Den vil både være krimi, kærlighedshistorie og opråb om klimaet. Til sidst ønsker man mest af alt, at den vælger.' Hvad er anmelderens kritik?","o":["Bogen spreder sig over for mange ting","Bogen er for kort til sine temaer","Bogen handler for meget om kærlighed","Bogen vælger forkert mellem sine personer"],"a":"Bogen spreder sig over for mange ting","r":"'Vil meget' lyder først positivt, men 'at den vælger' viser, at bogen mangler fokus. Der er ingen kritik af længden."},
{"l":7771,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Hun måtte ___ forlade rummet, da alarmen gik.'","o":["øjenblikkelig","øjeblikkelig","øjeblikelig","øjeblikkeli"],"a":"øjeblikkelig","r":"Første led hedder 'øje-' uden n, og 'blik' får dobbelt-k foran endelsen."},
{"l":7788,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken sætning appellerer først og fremmest til patos?","o":["Tal fra kommunen viser, at besøgene er faldet med ti procent.","Som sygeplejerske gennem mange år kender jeg dette område.","Hver dag sidder en ensom kvinde og venter forgæves på besøg.","Besøgstiden på plejehjemmet er mellem klokken ti og tolv."],"a":"Hver dag sidder en ensom kvinde og venter forgæves på besøg.","r":"Billedet af den ensomme kvinde skal vække medfølelse. Sætningen med tal er logos, og den med sygeplejersken er etos."},
{"l":7807,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvordan ser en 'misantrop' på andre mennesker?","o":["med stor nysgerrighed","med varm hengivenhed","med dyb beundring","med mistro og uvilje"],"a":"med mistro og uvilje","r":"'Mis' kommer af det græske ord for had, og 'antrop' betyder menneske. En misantrop er altså det modsatte af en filantrop."},
{"l":7828,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken udgave af sætningen om brevet er mest formel?","o":["Vi udsendte brevet til alle forældre.","Vi fik lige sendt brevet ud til folk.","Vi smed brevet ud til alle forældre.","Vi skød brevet af sted til forældrene."],"a":"Vi udsendte brevet til alle forældre.","r":"Det fast sammensatte verbum 'udsende' er mere formelt end 'sende ud'. De andre sætninger er talesprog."},
{"l":7844,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Enten forbyder vi alle telefoner i skolen, eller også lærer eleverne aldrig noget.' Hvilken argumentationsfejl er det?","o":["personangreb","falsk dilemma","cirkelslutning","forhastet generalisering"],"a":"falsk dilemma","r":"Der stilles kun to yderpunkter op, selv om der findes mange mellemløsninger. Derfor er valget falsk."},
{"l":7869,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'I morgen skal Selma ___ sit projekt for klassen.'","o":["præsenterer","præsentære","præsentere","pressentere"],"a":"præsentere","r":"Efter 'skal' står navneform, så der er ikke -r til sidst. Ordet har præ- og ét s."},
{"l":7889,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad sker der, når en roman bliver 'adapteret' til film?","o":["den bliver oversat til et fremmed sprog","den bliver forbudt i landets biografer","den bliver udgivet i en billig udgave","den bliver bearbejdet til det nye medie"],"a":"den bliver bearbejdet til det nye medie","r":"At adaptere er at tilpasse. Filmen skal fortælle historien på sin egen måde, så handlingen må tit ændres og forkortes."},
{"l":7911,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Der er et ___ til bussen: Du kan cykle.'","o":["alternativ","alternatif","allternativ","altenativ"],"a":"alternativ","r":"Ordet har ét l, og det slutter på -iv, som mange fremmedord."},
{"l":7928,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hey, er du også træt af en kedelig skoletaske? Fedt, for nu kommer den i nye, seje farver!' Hvem er reklamens målgruppe?","o":["Pensionister","Unge skoleelever","Lærere på skolen","Forældre til spædbørn"],"a":"Unge skoleelever","r":"Ord som 'hey', 'fedt' og 'seje' og selve varen, skoletasken, peger på unge elever."},
{"l":7949,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvem er 'drotten' i et gammelt kvad?","o":["fjenden","skjalden","kongen","bonden"],"a":"kongen","r":"'Drot' er et gammelt ord for konge eller fyrste. Det ligger også i ordet 'dronning'."},
{"l":7971,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er en anglicisme: 'Vi chillede hele aftenen i haven.'?","o":["aftenen","haven","hele","chillede"],"a":"chillede","r":"En anglicisme er påvirkning fra engelsk. 'Chille' kommer af engelsk 'chill' og har fået danske endelser."},
{"l":7993,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad kalder man den enkelte persons helt egen sprogbrug?","o":["idiolekt","dialekt","sociolekt","rigsdansk"],"a":"idiolekt","r":"'Idio' betyder 'egen'. En idiolekt er det sprog, netop du taler, med dine ord og vendinger."},
{"l":8009,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find rigtigt: 'Det handler om kvalitet og ikke om ___, altså mængden af noget.'","o":["kvantitæt","kvantitet","kvanntitet","quantitet"],"a":"kvantitet","r":"Ordet betyder mængde. Det staves med kv og ét n og ender på -tet, ligesom kvalitet."},
{"l":8030,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma, når leddet gentages af et stedord: 'Min farmor hun kan alt.'?","o":["hun","kan","farmor","alt"],"a":"farmor","r":"'Min farmor' står løst foran sætningen og gentages af 'hun'. Et sådant løsrevet led skilles fra med komma."},
{"l":8048,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er hovedsætningen i: 'Den bog, som Ali lånte, var spændende.'?","o":["som Ali lånte","Ali lånte","bog, som Ali lånte","Den bog var spændende"],"a":"Den bog var spændende","r":"Relativsætningen står inde i hovedsætningen. Tager man den ud, står hovedsætningen tilbage."},
{"l":8070,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning har en fejl i ordstillingen?","o":["Vi gik, da vi havde ikke mere at lave.","Vi gik, da vi ikke havde mere at lave.","Da vi ikke havde mere at lave, gik vi.","Vi havde ikke mere at lave, så vi gik."],"a":"Vi gik, da vi havde ikke mere at lave.","r":"I ledsætningen med 'da' skal 'ikke' stå foran verbet. I den sidste sætning er 'Vi havde ikke' en hovedsætning, og der er det rigtigt."},
{"l":8093,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad kalder man en bog om en persons liv? Vælg den rigtige stavemåde.","o":["biographi","biografi","biograffi","bioggrafi"],"a":"biografi","r":"Ordet kommer fra græsk 'bios', der betyder liv, og 'graphein', der betyder at skrive. På dansk bruges f."},
{"l":8114,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning bruger flest verber gjort til navneord (nominaliseringer)?","o":["Vi undersøgte det, og tallet steg en del.","De talte igen, og så var der flere end før.","Undersøgelsen viste en stigning i antallet.","Da vi kiggede efter, var der kommet flere."],"a":"Undersøgelsen viste en stigning i antallet.","r":"'Undersøgelse' og 'stigning' er dannet af verberne 'undersøge' og 'stige'. Det er typisk for fagligt og formelt sprog."},
{"l":8130,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken skikkelse i nordisk mytologi er kendt for at være snu og drilsk og skabe problemer for guderne?","o":["Thor","Odin","Balder","Loke"],"a":"Loke","r":"Loke er den upålidelige snydepels blandt aserne. Hans påfund driver mange af myterne frem."},
{"l":8158,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes det, når en tekst tydeligt henviser til eller bygger på en anden tekst?","o":["intertekstualitet","kronologi","personifikation","komposition"],"a":"intertekstualitet","r":"Intertekstualitet betyder, at tekster taler med hinanden, f.eks. når en roman låner fra et kendt eventyr."},
{"l":8177,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Elevrådet vil ___ en fest for hele skolen.'","o":["arangere","arrangere","arrangerer","arrangjere"],"a":"arrangere","r":"Ordet har dobbelt-r og står i navneform efter 'vil'."},
{"l":8198,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læreren bad om en 'koncis' opsummering. Hvordan skal den være?","o":["lang og grundig","sjov og personlig","kort og præcis","fri og fantasifuld"],"a":"kort og præcis","r":"Koncis betyder kortfattet uden at miste det vigtige. Det er en kvalitet ved gode resuméer."},
{"l":8218,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I en gruppe på ti elever får ni 100 kroner om måneden i lommepenge, og én får 1.100 kroner. Gennemsnittet er 200 kroner.' Hvorfor er gennemsnittet misvisende her?","o":["Gennemsnittet er regnet forkert ud fra elevernes lommepenge","Der er for mange elever i gruppen til at regne på","Ti elever får tilsammen mindre end 200 kroner","Én høj værdi trækker tallet langt op over det typiske"],"a":"Én høj værdi trækker tallet langt op over det typiske","r":"Ingen af de ti får faktisk 200 kroner. Tallet er rigtigt regnet, men det beskriver hverken de ni eller den ene."},
{"l":8240,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Han stod med bolden under armen, mens holdene blev valgt. Først blev der kaldt på Noah. Så på Ali. Så på Anders, der havde brækket armen og kun var med for at se på.' Hvad gør den sidste oplysning?","o":["Den viser, hvor lavt drengen står i de andres øjne","Den forklarer, hvorfor Anders er klassens bedste spiller","Den viser, at holdene blev valgt helt tilfældigt af læreren","Den gør det klart, at drengen også selv har brækket armen"],"a":"Den viser, hvor lavt drengen står i de andres øjne","r":"Når selv en dreng, der ikke kan spille, bliver valgt før ham, står han helt nederst. Det er både sjovt og smertefuldt."},
{"l":8258,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'herkulesopgave'?","o":["en lille og hurtig opgave","en enorm og krævende opgave","en hemmelig og farlig opgave","en gammel og glemt opgave"],"a":"en enorm og krævende opgave","r":"Herkules var en stærk helt i oldtidens myter, som skulle udføre tolv umulige arbejder. Derfor bruges navnet om noget, der kræver enorme kræfter."},
{"l":8282,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'en malurt i bægeret'?","o":["noget, der gør en svær dag en smule lettere","noget, der giver hurtig hjælp mod en sygdom","noget, der ødelægger en ellers god oplevelse","noget, der smager sødt, men koster meget"],"a":"noget, der ødelægger en ellers god oplevelse","r":"Malurt er en bitter plante. Hælder man den i bægeret, bliver hele drikken bitter, og sådan kan en enkelt ting skæmme glæden."},
{"l":8303,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Vi bestilte ferien gennem et ___ for rejser.'","o":["byrå","bureu","buro","bureau"],"a":"bureau","r":"Ordet kommer fra fransk og skrives med -eau til sidst, selvom det lyder som o."},
{"l":8323,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type ledsætning er 'hvor vi mødtes' i: 'Caféen, hvor vi mødtes, er lukket nu.'?","o":["relativsætning","spørgende ledsætning","at-sætning","adverbialsætning"],"a":"relativsætning","r":"Ledsætningen siger noget nærmere om navneordet 'caféen'. Derfor er den en relativsætning, selv om den begynder med et hv-ord."},
{"l":8345,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Man skal ikke dømme folk på deres ___.'","o":["udsende","udseende","udseene","udsæende"],"a":"udseende","r":"Ordet består af 'ud' og 'seende', så der er to e'er efter hinanden. 'Udsende' betyder at sende ud."},
{"l":8370,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'tautologi'?","o":["et udsagn, der modsiger sig selv fra start til slut","et udsagn, der bygger på en lang række fakta og tal","et udsagn, der blot gentager sig selv med andre ord","et udsagn, der skal udtales meget hurtigt og uden fejl"],"a":"et udsagn, der blot gentager sig selv med andre ord","r":"'Han er ugift, for han har ingen kone' er en tautologi. Det andet led tilføjer ikke noget nyt, så sætningen forklarer intet."},
{"l":8389,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken lang form skal man skrive i en formel tekst i stedet for den korte 'ha': 'Vil du ha en is?'?","o":["haft","har","havde","have"],"a":"have","r":"Efter 'vil' står navneform. Den lange form 'have' passer i formel tekst, mens 'ha' er tæt på talesprog."},
{"l":8411,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Selv om klubben har mistet tre ud af fire sponsorer, siger formanden, at økonomien er sund.' Hvad gør ordene 'selv om' ved sætningen?","o":["De lægger op til, at læseren skal undre sig","De viser, at journalisten er enig med formanden","De forklarer, hvorfor sponsorerne har forladt klubben","De fortæller, at sponsorerne snart kommer igen"],"a":"De lægger op til, at læseren skal undre sig","r":"'Selv om' markerer en modsætning, så sætningen sår tvivl uden at sige noget direkte. Skrev man 'og', ville virkningen forsvinde."},
{"l":8433,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning kan omskrives til aktiv?","o":["De to venner mødes i byen.","Bordene flyttes af pedellen.","Hun længes efter sommeren.","Bjørne findes ikke i Danmark."],"a":"Bordene flyttes af pedellen.","r":"Kun her er s-formen passiv: 'Pedellen flytter bordene.' De andre verber er gensidige eller findes kun med -s i den betydning."},
{"l":8455,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'Jeg blev meget ___ over den fine gave.'?","o":["overraskende","overraske","overrasket","overrasker"],"a":"overrasket","r":"Kort tillægsform beskriver den, der oplever noget. Lang tillægsform beskriver det, der virker på en: 'en overraskende gave'."},
{"l":8475,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Han præsenterer sig som 'læge in spe'. Hvad betyder det?","o":["tidligere","kendt","pensioneret","kommende"],"a":"kommende","r":"'In spe' er latin for 'i håbet'. En læge in spe er altså en, der håber at blive læge og er på vej dertil."},
{"l":8498,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Moderen bad sønnen komme 'betids'. Hvornår skal han komme?","o":["i god tid","meget sent","om natten","ved første frost"],"a":"i god tid","r":"'Betids' er et ældre ord for i god tid, altså før det er for sent. Ordet rummer 'tid' og ses stadig af og til på skrift."},
{"l":8514,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'I 50 år har Hans Krogh passet sine æbletræer. Da han ikke længere kunne klatre, plantede han dværgtræer. – Nu må træerne komme mig i møde, siger han og griner.' Hvad viser hans udtalelse?","o":["At han er bitter over at blive gammel","At han tager sin alder med humor","At han vil holde op med at dyrke æbler","At træerne er blevet for høje for ham"],"a":"At han tager sin alder med humor","r":"Han vender en begrænsning til en spøg og finder en løsning. Latteren viser, at han ikke er bitter."},
{"l":8541,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Resultatet var ikke ___, så hun prøvede igen.'","o":["tilfredstillende","tilfredsstillene","tilfredsstillende","tilfreds stillende"],"a":"tilfredsstillende","r":"Ordet består af 'tilfreds' og 'stillende', så der skal to s'er midt i ordet, og -ende har d."},
{"l":8560,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Kære forældre. Skolen er et fælles projekt. Vi beder jer om at tjekke jeres barns taske hver aften, hjælpe med lektier, læse højt og møde op til alle arrangementer.' Hvad gør ordene 'et fælles projekt' i brevet?","o":["De forklarer, hvad skolen selv vil gøre fremover","De viser, at forældrene har foreslået det selv","De lover forældrene mere indflydelse på skemaet","De indpakker en lang række krav i venlige ord"],"a":"De indpakker en lang række krav i venlige ord","r":"Alt, der følger, er forældrenes opgaver, ikke skolens. Det fællesskab, ordene lover, er derfor mest en høflig indpakning."},
{"l":8586,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Ordet 'husene' kan deles i 'hus', 'e' og 'ne', og hver del bærer betydning. Hvad kaldes delene?","o":["morfemer","stavelser","fonemer","bogstaver"],"a":"morfemer","r":"Et morfem er den mindste del af et ord, der bærer betydning. Stavelser er noget andet: de deler ordet efter udtalen, hu-se-ne."},
{"l":8612,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad gør man, når man 'bagatelliserer' et problem?","o":["gør det større, end det egentlig er","gør det mindre, end det egentlig er","løser det, før andre opdager det","skriver det ned i en lang rapport"],"a":"gør det mindre, end det egentlig er","r":"En bagatel er en lille ting uden betydning. Man får altså noget alvorligt til at se ubetydeligt ud."},
{"l":8636,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Denne folder er betalt af sodavandsbranchen. Den vigtigste vej til sunde børn er bevægelse. Sæt jeres børn i gang med at løbe, spille og lege!' Hvad er den sandsynlige hensigt med at udsende folderen?","o":["At sælge sportsudstyr og løbesko til børn og forældre","At advare forældre mod for meget bevægelse hos børn","At lede opmærksomheden væk fra sukker i drikkevarer","At få skoler til at holde flere pauser om dagen"],"a":"At lede opmærksomheden væk fra sukker i drikkevarer","r":"Budskabet er rimeligt, men afsenderen er ikke tilfældig. Hvis bevægelse er det vigtigste, bliver sodavand mindre vigtigt."},
{"l":8658,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning skriver genitiv rigtigt af kongens navn med ordenstal?","o":["Christian 4's regeringstid var lang.","Christian 4:s regeringstid var lang.","Christian 4s. regeringstid var lang.","Christian 4.s regeringstid var lang."],"a":"Christian 4.s regeringstid var lang.","r":"Ordenstallet beholder sit punktum, og genitiv-s sættes direkte efter: 4.s."},
{"l":8680,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord fuldender sætningen: 'Forslaget var meget ___: Halvdelen af byen var for, og den anden halvdel var rasende.'","o":["kontroversielt","konventionelt","kompakt","konkret"],"a":"kontroversielt","r":"Noget kontroversielt skaber strid og deler vandene. Konventionelt betyder det modsatte: vanligt og uden at vække opsigt."},
{"l":8700,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Tak ___ for hjælpen til festen.'","o":["påforhånd","på forhånd","på forhand","på for hånd"],"a":"på forhånd","r":"Udtrykket består af to ord: 'på' og 'forhånd'."},
{"l":8718,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sprogfunktion er vigtigst i udbruddet: 'Av, hvor gør det ondt!'","o":["den informative","den metasproglige","den ekspressive","den poetiske"],"a":"den ekspressive","r":"Den ekspressive funktion udtrykker afsenderens egne følelser. Her er det smerten, der kommer ud, ikke en oplysning til andre."},
{"l":8740,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Hun havde en ___ følelse af, at noget var galt, men hun kunne ikke sætte ord på den.'","o":["skarp","konkret","tydelig","diffus"],"a":"diffus","r":"Diffus betyder uklar og spredt. Derfor kan hun ikke sige, hvad følelsen går ud på."},
{"l":8762,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad står i forfeltet i spørgsmålet: 'Har du set min taske?'","o":["Forfeltet er tomt.","'Har' står i forfeltet.","'du' står i forfeltet.","'min taske' står i forfeltet."],"a":"Forfeltet er tomt.","r":"Et ja/nej-spørgsmål begynder med det bøjede udsagnsord, så intet står foran det. Derfor er forfeltet tomt."},
{"l":8784,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led står i forfeltet i: 'Da Yusuf kom hjem, var maden kold.'","o":["Da Yusuf","Da Yusuf kom hjem","var maden","maden"],"a":"Da Yusuf kom hjem","r":"Hele ledsætningen er ét led, og den står foran det bøjede udsagnsord 'var'. Derfor kommer grundleddet 'maden' først bagefter."},
{"l":8805,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Da solen sank bag bøgene, stod vandreren stille. Skoven sukkede af en længsel, der var hans egen, og i hver dråbe dug anede han det uendelige. Aldrig havde han følt sig så fjernt fra byen og så nær alting.' Hvilken stilretning passer bedst?","o":["Naturalismen, fordi naturen beskrives så nøje, som var det videnskab","Modernismen, fordi jeget er splittet og ikke finder nogen sammenhæng","Romantikken, fordi naturen og mennesket smelter sammen i noget større","Realismen, fordi teksten gengiver et almindeligt menneskes hverdag"],"a":"Romantikken, fordi naturen og mennesket smelter sammen i noget større","r":"Besjælet natur og en længsel mod det uendelige er typisk for romantikken. Naturen er nok i centrum, men den beskrives ikke nøgternt, som naturalismen ville gøre."},
{"l":8826,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Far sagde, at vi godt kunne klare os uden bil. Vi kunne cykle, det var sundt. Han sagde det med den samme stemme, som da han sagde, at vi ikke behøvede at holde ferie, fordi vi boede så tæt på skoven.' Hvad er underforstået?","o":["At far er blevet optaget af motion og frisk luft","At familien snart skal flytte længere ind i skoven","At far er uenig med resten af familien om ferien","At familien mangler penge, selv om far ikke siger det"],"a":"At familien mangler penge, selv om far ikke siger det","r":"Sammenligningen af de to stemmer viser et mønster: Far forklarer mangler som gode valg. Fortælleren gennemskuer det."},
{"l":8845,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hun er leder 'ad interim'. Hvad betyder det?","o":["i en mellemperiode, indtil en ny er fundet","for resten af sin tid på arbejdspladsen","sammen med en anden leder fra afdelingen","uden at have nogen ansatte under sig"],"a":"i en mellemperiode, indtil en ny er fundet","r":"Latin 'interim' betyder imens. Hun leder altså stedet midlertidigt."},
{"l":8866,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der altid stå komma: 'Selvom vi vidste at det ville blive svært hvis alle var syge spillede vi kampen.'?","o":["alle","syge","spillede","kampen"],"a":"syge","r":"Hele den indledende ledsætning med de to andre inde i sig slutter efter 'syge'."},
{"l":8885,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Tilhængere af højere tilskud til busserne siger, at pengene kan tages fra vejbyggeri. Modstandere siger, at vejene også skal vedligeholdes, og at bussen ikke kan køre på huller.' Hvad accepterer begge sider tilsyneladende?","o":["At busserne er den vigtigste form for trafik i byen","At vejene ikke behøver at blive vedligeholdt længere","At budgettet er begrænset, så der skal prioriteres","At der ikke findes nogen huller i vejene i dag"],"a":"At budgettet er begrænset, så der skal prioriteres","r":"Begge taler om, hvor pengene skal gå hen, og ingen foreslår flere penge i alt. Det er den fælles forudsætning."},
{"l":8905,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken ændring kom med retskrivningsreformen i 1948?","o":["Bogstavet z blev fjernet fra det danske alfabet.","Alle kommaer foran ledsætninger blev helt afskaffet.","Stødet blev for første gang skrevet i retskrivningen.","Almindelige navneord fik lille begyndelsesbogstav."],"a":"Almindelige navneord fik lille begyndelsesbogstav.","r":"Før 1948 skrev man navneord med stort, som man stadig gør på tysk. Samme reform indførte også bogstavet å i stedet for aa."},
{"l":8926,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Den her solcreme må være god, for en kendt skuespiller bruger den.' Hvilken svaghed har argumentet?","o":["falsk autoritet","cirkelslutning","falsk dilemma","stråmand"],"a":"falsk autoritet","r":"Skuespilleren er kendt, men har ingen særlig viden om solcreme. Personens berømmelse gør ikke argumentet stærkere."},
{"l":8945,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Fra vinduet kunne man se den mark, som far havde solgt. Bedstemor stod der hver aften og talte, som hun sagde, køerne. Der havde ikke været køer i tolv år.' Hvad er mest sandsynligt om bedstemor?","o":["Hun er bange for at købe nye køer til gården","Hun lever i en tid, der ikke findes mere","Hun holder øje med naboens køer på marken","Hun er ved at planlægge at sælge marken"],"a":"Hun lever i en tid, der ikke findes mere","r":"Hun gør noget, der ikke længere har noget at gøre med virkeligheden. Det kan være glemsel eller sorg, men fortiden er stadig hendes nutid."},
{"l":8969,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det er bemærkelsesværdigt, hvor mange år det tog ledelsen at opdage, at eleverne også har en mening. Man må håbe, at opdagelsen ikke giver dem for travlt.' Hvilken slags ironi er der tale om?","o":["Venlig selvironi fra en af skolens ledere","Skæbnens ironi, hvor en plan slår fejl","Bidende ros, som i virkeligheden er en anklage","Dramatisk ironi, hvor læseren ved mere end personerne"],"a":"Bidende ros, som i virkeligheden er en anklage","r":"'Bemærkelsesværdigt' og 'opdage' lyder anerkendende, men pointen er, at ledelsen har været alt for sen. Det er sarkasme."},
{"l":8987,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Klassen var meget ___: Næsten alle elever kom fra samme kvarter og havde de samme interesser.'","o":["heterogen","hypotetisk","hermetisk","homogen"],"a":"homogen","r":"Homo- betyder samme, så homogen betyder ensartet. Heterogen er det modsatte og beskriver en blandet gruppe."},
{"l":9004,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Ingen kan være imod tryghed. Derfor kan ingen være imod kameraer på gangene.' Hvad springer argumentet over?","o":["Om kameraer er den rigtige vej til målet","Hvor mange kameraer skolen har brug for i alt","Om gangene er for lange på skolen","Hvad det koster at købe nye kameraer"],"a":"Om kameraer er den rigtige vej til målet","r":"Man kan godt ville tryghed, men ikke kameraer. Argumentet glider fra enighed om målet til enighed om midlet."},
{"l":9026,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"'Et råb' er dannet af 'at råbe' uden nogen afledningsendelse. Hvilket af disse ord er dannet på samme måde?","o":["en kørsel","et hop","en løber","en forklaring"],"a":"et hop","r":"'Et hop' kommer af 'at hoppe' uden en afledningsendelse. De andre ord har endelser: '-sel', '-er' og '-ing'."},
{"l":9048,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning bruger det rigtige henførende stedord, når stedordet er genstandsled?","o":["Filmen, der Karla anbefalede, var lang.","Filmen, hvilket Karla anbefalede, var lang.","Filmen, som Karla anbefalede, var lang.","Filmen, hvem Karla anbefalede, var lang."],"a":"Filmen, som Karla anbefalede, var lang.","r":"'Der' kan kun være grundled i ledsætningen. Her er 'Karla' grundled, og filmen er det, hun anbefaler, så det skal være 'som'."},
{"l":9070,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Forfatteren kalder sin hovedperson for sit 'alter ego'. Hvad mener hun med det?","o":["Personen er hendes værste fjende","Personen er lånt fra en meget ældre roman","Personen er bygget på hendes mor","Personen er en slags andet jeg for hende"],"a":"Personen er en slags andet jeg for hende","r":"Alter ego er latin for 'et andet jeg'. Man kan altså møde forfatterens egne træk og tanker i figuren."},
{"l":9090,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad hedder læren om, hvordan sætninger er opbygget? Vælg den rigtige stavemåde.","o":["syntaks","sintaks","syntagks","suntaks"],"a":"syntaks","r":"Ordet kommer fra græsk og skrives med y og ks til sidst."},
{"l":9107,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Truslen om lukning hang som et damoklessværd over skolen.' Hvad udtrykker billedet?","o":["en gammel strid, som ingen husker","en fare, der kan ramme når som helst","en stor ære, der venter forude","en fejl, der allerede er rettet"],"a":"en fare, der kan ramme når som helst","r":"Damokles sad ifølge sagnet under et sværd, der kun hang i et enkelt hestehår. Billedet bruges om en truende fare."},
{"l":9125,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"I hvilken af sætningerne er '-er' i ordet 'maler' et afledningsmorfem og ikke en bøjningsendelse?","o":["Min onkel maler huset.","Hver sommer maler han.","Min onkel er maler.","Han maler også skure."],"a":"Min onkel er maler.","r":"I 'Min onkel er maler' er '-er' en afledning, der laver et navneord af udsagnsordet: en person, der maler. I de andre sætninger er 'maler' udsagnsord, og endelsen viser blot nutid."},
{"l":9150,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad skal der stå? 'Han prøvede at ___ sin bror med drillerier.'","o":["provocere","provokkere","pravokere","provokere"],"a":"provokere","r":"På dansk skrives ordet med ét k og ikke med c."},
{"l":9169,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har først og fremmest en metasproglig funktion?","o":["Ordet 'hygge' er et navneord.","Det er hyggeligt hos dig i dag.","Kom og hyg dig sammen med os.","Vi hyggede os hele aftenen."],"a":"Ordet 'hygge' er et navneord.","r":"Metasprog er sprog om sprog. Sætningen taler om selve ordet 'hygge' og ikke om det at hygge sig."},
{"l":9190,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"I H.C. Andersens 'Nattergalen' bliver en levende fugl erstattet af en kunstig. Hvilken modsætning er central?","o":["Det gamle og det nye tøj ved hoffet","Det ægte og levende over for det kunstige","Det rige og det fattige land på kortet","Dag og nat i den kinesiske hovedstad"],"a":"Det ægte og levende over for det kunstige","r":"Den mekaniske fugl er skinnende, men kan kun gentage det samme. Den levende nattergal kan røre mennesker."},
{"l":9210,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Historiens ___ kom helt til sidst og fik alle til at grine.'","o":["poengte","poinnte","pointe","pwente"],"a":"pointe","r":"Ordet kommer fra fransk og skrives med oi og -nte."},
{"l":9230,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning skriver 'ph.d.' rigtigt sammen med et andet ord?","o":["Hun skriver en ph.d-afhandling om sprog.","Hun skriver en ph.d. afhandling om sprog.","Hun skriver en phd.-afhandling om sprog.","Hun skriver en ph.d.-afhandling om sprog."],"a":"Hun skriver en ph.d.-afhandling om sprog.","r":"Forkortelsen beholder begge sine punktummer, og bindestregen binder den til det næste ord."},
{"l":9250,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Familien ville helst ikke tale om arven, for det var et ___ emne.'","o":["ømtåleligt","muntert","festligt","ubekymret"],"a":"ømtåleligt","r":"Et ømtåleligt emne er følsomt og kan let gøre ondt eller skabe strid. Derfor undgår familien at tale om det."},
{"l":9268,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord indeholder lyden [ŋ]?","o":["sende","synge","sagde","sige"],"a":"synge","r":"[ŋ] er ng-lyden, der dannes bag i munden. I 'sende' høres et almindeligt n, og i 'sagde' og 'sige' er der ingen næselyd."},
{"l":9290,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilke to gamle køn er i rigsdansk smeltet sammen til fælleskøn?","o":["hankøn og intetkøn","hunkøn og intetkøn","hankøn og hunkøn","intetkøn og tvekøn"],"a":"hankøn og hunkøn","r":"Ældre dansk havde tre køn. Hankøn og hunkøn faldt sammen til fælleskøn ('en'), mens intetkøn ('et') blev bevaret."},
{"l":9311,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er et hovedemne i J.P. Jacobsens 'Niels Lyhne'?","o":["En families kamp for at få fisk nok om vinteren","En ung piges flugt fra et gods i middelalderen","En gruppe arbejderes strejke på en fabrik","Et menneskes forsøg på at leve uden tro på Gud"],"a":"Et menneskes forsøg på at leve uden tro på Gud","r":"Romanen følger Niels Lyhne, der forsøger at leve som fritænker. Det var et stærkt tema i det moderne gennembrud."},
{"l":9333,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken forfatter skrev om kvinders vilkår i romanen 'Constance Ring' fra 1885?","o":["Amalie Skram","Karin Michaëlis","Thit Jensen","Agnes Henningsen"],"a":"Amalie Skram","r":"Den norsk-danske forfatter Amalie Skram skildrede ægteskab og kvinders vilkår i naturalismens nøgterne stil."},
{"l":9355,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er universalromantikkens grundtanke?","o":["Alle lande bør have det samme sprog og flag","Alt hænger sammen i en guddommelig helhed","Alle mennesker skal rejse jorden rundt én gang","Kun naturvidenskaben kan forklare verden"],"a":"Alt hænger sammen i en guddommelig helhed","r":"Universalromantikerne så natur, menneske og ånd som ét. Digteren kan ane helheden bag det enkelte."},
{"l":9375,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'I nordisk ___ er Thor tordenguden.'","o":["mythologi","mytollogi","mytologi","mutologi"],"a":"mytologi","r":"Ordet kommer fra græsk 'mythos', men på dansk er der intet h."},
{"l":9392,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"'Det var den bedste af tider, det var den værste af tider.' Hvilken figur bygger sætningen på?","o":["anagram","anekdote","analogi","antitese"],"a":"antitese","r":"En antitese stiller to modsætninger skarpt over for hinanden. Sætningen indleder Charles Dickens' 'En fortælling om to byer'."},
{"l":9415,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilken gren af sprogvidenskaben beskæftiger sig med ords og sætningers betydning?","o":["semantik","fonetik","morfologi","syntaks"],"a":"semantik","r":"Semantik kommer af græsk for tegn. Fonetik handler om lyde, morfologi om ordenes bygning og syntaks om sætninger."},
{"l":9438,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilke to ord skal der altid stå komma: 'Hvis Ida kommer som hun lovede kan vi begynde men Noah mangler stadig.'?","o":["kommer og begynde","lovede og begynde","Ida og lovede","kan og Noah"],"a":"lovede og begynde","r":"Ledsætningen slutter efter 'lovede', og foran 'men' skal der komma. Komma efter 'kommer' er et valgfrit startkomma."},
{"l":9460,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Kritikeren kalder en tale 'bombastisk'. Hvordan er talen?","o":["kort og præcis i alle sine pointer","stille og beskeden i sin fremførelse","højtravende og overdrevent svulstig","farlig og truende over for tilhørerne"],"a":"højtravende og overdrevent svulstig","r":"Bombast var oprindeligt et stof til polstring. Bombastisk tale er polstret med store ord, men har ikke noget med bomber at gøre."},
{"l":9480,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad skal der stå? 'Mel er den vigtigste ___ i brød.'","o":["ingredienz","ingrediæns","ingredient","ingrediens"],"a":"ingrediens","r":"På dansk ender ordet på -ens. Engelsk 'ingredient' må ikke forveksles med det."},
{"l":9498,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Far sagde, at onkel Ib var rejst langt væk. Mor græd i køkkenet. Det var nok løgene, tænkte jeg, for hun var ved at lave suppe.' Hvad opnår forfatteren med barnets synsvinkel?","o":["Læseren forstår mere, end barnet selv gør","Læseren får alle voksnes tanker at vide","Læseren bliver sikker på, at mor laver mad","Læseren får en præcis oversigt over tiden"],"a":"Læseren forstår mere, end barnet selv gør","r":"Barnet tolker det, det ser, uskyldigt, mens læseren aner en større sorg. Afstanden mellem de to giver teksten sin styrke."},
{"l":9520,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Meteorologen stod gennemblødt ved bussen, for hun havde selv lovet tørvejr og ladet paraplyen blive hjemme.' Hvilken slags ironi er der her?","o":["verbal ironi","situationsironi","dramatisk ironi","selvironi"],"a":"situationsironi","r":"Ironien ligger i selve situationen, ikke i noget, nogen siger: Netop hende burde vejret ikke kunne overraske."},
{"l":9542,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kaldes et billede eller en ting, der vender tilbage gennem et værk og binder det sammen?","o":["anslag","stilleje","ledemotiv","kiasme"],"a":"ledemotiv","r":"Et ledemotiv går igen og får ny betydning undervejs. Det binder værket sammen."},
{"l":9564,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Romanens kapitler skifter mellem en pige i 1944 og hendes barnebarn i vores tid, og først til sidst mødes de to spor. Hvilken komposition er det?","o":["cirkelkomposition","kronologisk komposition","in medias res","parallelkomposition"],"a":"parallelkomposition","r":"To handlingsspor løber side om side og belyser hinanden. Det er en parallelkomposition."},
{"l":9585,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvordan staves ordet? 'Hun startede sin ___ som skuespiller på en lille scene.'","o":["karriere","karierre","kariere","karrierre"],"a":"karriere","r":"Ordet kommer fra fransk: dobbelt-r først, ét r sidst og ie imellem."},
{"l":9600,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Tegningen var en ___, som overdrev skuespillerens lange næse.'","o":["karrikatur","karikatur","karikaktur","kariktur"],"a":"karikatur","r":"Ordet har ét r i anden stavelse og ét til sidst: ka-ri-ka-tur."},
{"l":9620,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket tegn gør sætningen forkert: 'Der var kun én vej ud ___ gennem skoven.'?","o":["kolon","tankestreg","bindestreg","komma"],"a":"bindestreg","r":"Bindestreg binder ord sammen og kan ikke markere pausen her. De tre andre tegn kan alle stå foran forklaringen."},
{"l":9645,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Hun stod i et ___: Begge valg ville skuffe nogen.'","o":["dillemma","dilema","dillema","dilemma"],"a":"dilemma","r":"Ordet kommer fra græsk og har ét l og dobbelt-m."},
{"l":9664,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Danske dialekter deles ofte i tre hovedgrupper: jysk, ømål og østdansk. Hvor hører bornholmsk hjemme?","o":["østdansk","jysk","ømål","sønderjysk"],"a":"østdansk","r":"Bornholmsk er den østdanske dialekt, der er tilbage i Danmark. Ømål tales på Sjælland, Fyn og øerne omkring dem."},
{"l":9685,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'jeg går / gennem dagen / som gennem et tomt hus / hvor lyset står tændt' Hvilket sprogligt billede er brugt i tredje linje?","o":["metonymi","sammenligning","oxymoron","synæstesi"],"a":"sammenligning","r":"Ordet 'som' sammenligner dagen med et tomt hus. Billedet giver en følelse af tomhed og forladthed."},
{"l":9707,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I en debat kalder man en person for en 'kassandra'. Hvad gør vedkommende?","o":["spreder falske rygter om modstandere","taler altid for at bevare det bestående","advarer om ulykker uden at blive troet","roser sig selv ved enhver lejlighed"],"a":"advarer om ulykker uden at blive troet","r":"Kassandra var en trojansk prinsesse, der kunne se fremtiden. Hendes forbandelse var, at ingen troede på hende."},
{"l":9729,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Alle i byen kendte hr. Holm, og alle var enige om, at han var en fremragende mand. Han havde jo penge.' Hvad gør fortælleren?","o":["Roser ærligt hr. Holms gode karakter","Forklarer, hvordan man bliver rig i byen","Beskriver neutralt hr. Holms hverdag","Kritiserer med ironi byens syn på penge"],"a":"Kritiserer med ironi byens syn på penge","r":"Den sidste korte sætning afslører, at han kun er 'fremragende', fordi han er rig. Fortælleren håner stille byens målestok."},
{"l":9750,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Alle ___ stemte for forslaget på mødet.'","o":["tilstedeværende","tilstede værende","tilstedeværene","til stedeværende"],"a":"tilstedeværende","r":"Selvom man er 'til stede' i to ord, skrives det afledte ord i ét. Husk -ende med d."},
{"l":9767,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at en person virker 'tilforladelig'?","o":["at personen virker ensom og forladt af alle","at man føler, at personen er til at stole på","at personen virker hovmodig og kold over for andre","at personen har svært ved at tage afsked"],"a":"at man føler, at personen er til at stole på","r":"Ordet kommer af 'forlade sig på', altså at stole på noget. Det har intet at gøre med at blive forladt."},
{"l":9790,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Jeg lod ham vinde. Det har jeg sagt i fyrre år, hver gang nogen spurgte til den kamp. Der er kun én, der kan modsige mig, og han bor i Australien.' Hvad antyder sidste sætning?","o":["At fortælleren snart vil tage til Australien for at møde ham","At modstanderen var langt bedre end nogen anden i klubben","At historien måske ikke er sand, men ingen kan modsige den","At kampen slet ikke fandt sted, fordi han var i Australien"],"a":"At historien måske ikke er sand, men ingen kan modsige den","r":"Hvis historien var sikker, var der ingen grund til at nævne, at vidnet er langt væk. Fortælleren røber sig selv."},
{"l":9807,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har den rigtige form af tillægsordet, når grundleddet er en navneform?","o":["At løbe hver dag er sund.","At løbe hver dag er sunde.","At løbe hver dag er sunds.","At løbe hver dag er sundt."],"a":"At løbe hver dag er sundt.","r":"Når grundleddet er en navneform eller en at-sætning, står tillægsordet i intetkønsform. 'At løbe' har ingen køn, så -t-formen er standard."},
{"l":9828,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvorfor er titlen vigtig, når man læser Martin A. Hansens 'Løgneren'?","o":["Den får læseren til at tvivle på jeg-fortælleren","Den fortæller, at bogen er en detektivhistorie","Den viser, at alle på øen er kriminelle","Den forklarer, hvorfor bogen er for voksne"],"a":"Den får læseren til at tvivle på jeg-fortælleren","r":"Når fortælleren er selve 'løgneren', må læseren spørge, hvad der er sandt. Titlen gør ham til en upålidelig fortæller."},
{"l":9850,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken roman af J.P. Jacobsen fra 1876 skildrer en adelskvinde i 1600-tallet?","o":["Ved Vejen","Fru Marie Grubbe","Constance Ring","Tine"],"a":"Fru Marie Grubbe","r":"Marie Grubbe var en virkelig person. J.P. Jacobsen brugte hendes historie til at undersøge lidenskab og samfund."},
{"l":9873,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Fremmedordet 'demokrati' består af to græske dele. Hvad betyder de?","o":["land og lov","frihed og stemme","folk og magt","by og råd"],"a":"folk og magt","r":"'Demos' betyder folk, og 'kratos' betyder magt eller styre. Det samme '-krati' findes i ord som 'aristokrati'."},
{"l":9895,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken modus står udsagnsordet i: 'Længe leve fødselaren!'","o":["imperativ","indikativ","infinitiv","konjunktiv"],"a":"konjunktiv","r":"Konjunktiv er ønskeformen. Den findes næsten kun i faste udtryk på dansk, og den kendes på, at den ender på -e, selvom den har et grundled."},
{"l":9915,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find ordet: 'Hun skrev af fra nettet, og læreren kaldte opgaven for et ___.'","o":["plagiat","plagjat","plaggiat","plasiat"],"a":"plagiat","r":"Ordet kommer fra latin og skrives med ét g og i efter g'et."},
{"l":9932,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken af påstandene om komma er rigtig?","o":["Der skal altid komma foran 'og' i alle sætninger","Der skal komma efter en ledsætning, der står først","Der skal komma mellem grundled og udsagnsled","Der skal komma efter et forholdsled i sætningsstart"],"a":"Der skal komma efter en ledsætning, der står først","r":"Slutkommaet efter en ledsætning er et fast krav. De andre påstande er typiske misforståelser."},
{"l":9955,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Reglerne for fodbold gælder 'mutatis mutandis' også for indendørsfodbold. Hvad betyder det?","o":["helt uden nogen form for ændringer","kun i kampe med en autoriseret dommer","med de ændringer, der er nødvendige","indtil nye regler træder i kraft"],"a":"med de ændringer, der er nødvendige","r":"Latin 'mutatis mutandis' betyder 'når det, der skal ændres, er ændret'. Reglerne overføres og tilpasses."},
{"l":9975,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg det sammensatte ord: 'Med pludselige mavesmerter kom hun på hospitalet med ___.'","o":["blindtarmbetændelse","blintarmsbetændelse","blindtarmsbetendelse","blindtarmsbetændelse"],"a":"blindtarmsbetændelse","r":"Ordet samles med fuge-s efter 'blindtarm'. Husk d'et i 'blind' og æ'et i 'betændelse'."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
